   196	static int ptls_set_ecdsa_private_key(ptls_context_t *ctx, ptls_asn1_pkcs8_private_key_t *pkey, ptls_minicrypto_log_ctx_t *log_ctx)
   197	{
   198	    uint8_t *bytes = pkey->vec.base + pkey->parameters_index;
   199	    size_t bytes_max = pkey->parameters_length;
   200	    size_t byte_index = 0;
   201	    uint8_t *curve_id = NULL;
   202	    uint32_t curve_id_length = 0;
   203	    int decode_error = 0;
   204	    uint32_t seq_length;
   205	    size_t last_byte = 0;
   206	    uint8_t *ecdsa_key_data = NULL;
   207	    uint32_t ecdsa_key_data_length = 0;
   208	    size_t ecdsa_key_data_last = 0;
   209	
   210	    /* We expect the parameters to include just the curve ID */
   211	
   212	    byte_index = ptls_asn1_get_expected_type_and_length(bytes, bytes_max, byte_index, 0x06, &curve_id_length, NULL, &last_byte,
   213	                                                        &decode_error, log_ctx);
   214	
   215	    if (decode_error == 0 && bytes_max != last_byte) {
   216	        byte_index = ptls_asn1_error_message("Length larger than parameters", bytes_max, byte_index, 0, log_ctx);
   217	        decode_error = PTLS_ERROR_BER_EXCESSIVE_LENGTH;
   218	    }
   219	
   220	    if (decode_error == 0) {
   221	        curve_id = bytes + byte_index;
   222	
   223	        if (log_ctx != NULL) {
   224	            /* print the OID value */
   225	            log_ctx->fn(log_ctx->ctx, "Curve: ");
   226	            ptls_asn1_dump_content(curve_id, curve_id_length, 0, log_ctx);
   227	            log_ctx->fn(log_ctx->ctx, "\n");
   228	        }
   229	    }
   230	
   231	    /* We expect the key data to follow the ECDSA structure per RFC 5915 */
   232	    bytes = pkey->vec.base + pkey->key_data_index;
   233	    bytes_max = pkey->key_data_length;
   234	    byte_index = 0;
   235	
   236	    /* decode the wrapping sequence */
   237	    if (decode_error == 0) {
   238	        byte_index = ptls_asn1_get_expected_type_and_length(bytes, bytes_max, byte_index, 0x30, &seq_length, NULL, &last_byte,
   239	                                                            &decode_error, log_ctx);
   240	    }
   241	
   242	    if (decode_error == 0 && bytes_max != last_byte) {
   243	        byte_index = ptls_asn1_error_message("Length larger than key data", bytes_max, byte_index, 0, log_ctx);
   244	        decode_error = PTLS_ERROR_BER_ELEMENT_TOO_SHORT;
   245	    }
   246	
   247	    /* verify and skip the version number 1 */
   248	    if (decode_error == 0) {
   249	        /* get first component: version, INTEGER, expect value 0 */
   250	        if (byte_index + 3 > bytes_max) {
   251	            byte_index = ptls_asn1_error_message("Cannot find ECDSA Key Data Version", bytes_max, byte_index, 0, log_ctx);
   252	            decode_error = PTLS_ERROR_INCORRECT_ASN1_ECDSA_KEY_SYNTAX;
   253	        } else if (bytes[byte_index] != 0x02 || bytes[byte_index + 1] != 0x01 || bytes[byte_index + 2] != 0x01) {
   254	            decode_error = PTLS_ERROR_INCORRECT_PEM_ECDSA_KEY_VERSION;
   255	            byte_index = ptls_asn1_error_message("Incorrect ECDSA Key Data Version", bytes_max, byte_index, 0, log_ctx);
   256	        } else {
   257	            byte_index += 3;
   258	            if (log_ctx != NULL) {
   259	                log_ctx->fn(log_ctx->ctx, "ECDSA Version = 1,\n");
   260	            }
   261	        }
   262	    }
   263	
   264	    /* obtain the octet string that contains the ECDSA private key */
   265	    if (decode_error == 0) {
   266	        byte_index = ptls_asn1_get_expected_type_and_length(bytes, last_byte, byte_index, 0x04, &ecdsa_key_data_length, NULL,
   267	                                                            &ecdsa_key_data_last, &decode_error, log_ctx);
   268	
   269	        if (decode_error == 0) {
   270	            ecdsa_key_data = bytes + byte_index;
   271	        }
   272	    }
   273	
   274	    /* If everything is fine, associate the ECDSA key with the context */
   275	    if (curve_id_length == sizeof(ptls_asn1_curve_secp256r1) && curve_id != NULL &&
   276	        memcmp(curve_id, ptls_asn1_curve_secp256r1, sizeof(ptls_asn1_curve_secp256r1)) == 0) {
   277	        if (SECP256R1_PRIVATE_KEY_SIZE != ecdsa_key_data_length) {
   278	            decode_error = PTLS_ERROR_INCORRECT_PEM_ECDSA_KEYSIZE;
   279	            if (log_ctx != NULL) {
   280	                /* print the OID value */
   281	                log_ctx->fn(log_ctx->ctx, "Wrong SECP256R1 key length, %d instead of %d.\n", ecdsa_key_data_length,
   282	                            SECP256R1_PRIVATE_KEY_SIZE);
   283	            }
   284	        } else {
   285	            ptls_minicrypto_secp256r1sha256_sign_certificate_t *minicrypto_sign_certificate;
   286	
   287	            minicrypto_sign_certificate = (ptls_minicrypto_secp256r1sha256_sign_certificate_t *)malloc(
   288	                sizeof(ptls_minicrypto_secp256r1sha256_sign_certificate_t));
   289	
   290	            if (minicrypto_sign_certificate == NULL) {
   291	                decode_error = PTLS_ERROR_NO_MEMORY;
   292	            } else {
   293	                memset(minicrypto_sign_certificate, 0, sizeof(ptls_minicrypto_secp256r1sha256_sign_certificate_t));
   294	                decode_error = ptls_minicrypto_init_secp256r1sha256_sign_certificate(
   295	                    minicrypto_sign_certificate, ptls_iovec_init(ecdsa_key_data, ecdsa_key_data_length));
   296	            }
   297	            if (decode_error == 0) {
   298	                ctx->sign_certificate = &minicrypto_sign_certificate->super;
   299	
   300	                if (log_ctx != NULL) {
   301	                    /* print the OID value */
   302	                    log_ctx->fn(log_ctx->ctx, "Initialized SECP512R1 signing key with %d bytes.\n", ecdsa_key_data_length);
   303	                }
   304	            } else if (log_ctx != NULL) {
   305	                log_ctx->fn(log_ctx->ctx, "SECP512R1 init with %d bytes returns %d.\n", ecdsa_key_data_length, decode_error);
   306	            }
   307	        }
   308	    } else {
   309	        decode_error = PTLS_ERROR_INCORRECT_PEM_ECDSA_CURVE;
   310	        if (log_ctx != NULL) {
   311	            /* print the OID value */
   312	            log_ctx->fn(log_ctx->ctx, "Curve is not supported for signatures.\n");
   313	        }
   314	    }
   315	
   316	    return decode_error;
   317	}
